class Solution {
public:
    bool isPreorder(vector<vector<int>>& nodes) {
        vector<int> stack;
        for (const auto& node : nodes) {
            int id = node[0], parentId = node[1];
            if (parentId == -1) {
                stack.push_back(id);
                continue;
            }
            while (!stack.empty() && stack.back() != parentId) {
                stack.pop_back();
            }
            if (stack.empty()) return false;
            stack.push_back(id);
        }
        return true;
    }
};

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

class Solution {
    public boolean isPreorder(List<List<Integer>> nodes) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (List<Integer> node : nodes) {
            int id = node.get(0), parentId = node.get(1);
            if (parentId == -1) {
                stack.push(id);
                continue;
            }
            while (!stack.isEmpty() && stack.peek() != parentId) {
                stack.pop();
            }
            if (stack.isEmpty()) return false;
            stack.push(id);
        }
        return true;
    }
}

var isPreorder = function(nodes) {
    const stack = [];
    for (const [id, parentId] of nodes) {
        if (parentId === -1) {
            stack.push(id);
            continue;
        }
        while (stack.length > 0 && stack[stack.length - 1] !== parentId) {
            stack.pop();
        }
        if (stack.length === 0) return false;
        stack.push(id);
    }
    return true;
};
